import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  root: import.meta.dirname,
  server: {
    port: 5173,
    proxy: {
      '/api': 'http://localhost:3000',
    },
  },
  build: {
    outDir: '../public',
    emptyOutDir: true,
  },
});

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.jsx';
import './index.css';

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <App />
  </StrictMode>
);

export async function api(path, options = {}) {
  const res = await fetch(path, {
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });
  if (res.status === 204) return null;
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(data.error || `Request failed (${res.status})`);
  }
  return data;
}

export function fetchTodos() {
  return api('/api/todos');
}

export function createTodo(title) {
  return api('/api/todos', {
    method: 'POST',
    body: JSON.stringify({ title }),
  });
}

export function updateTodo(id, body) {
  return api(`/api/todos/${id}`, {
    method: 'PATCH',
    body: JSON.stringify(body),
  });
}

export function deleteTodo(id) {
  return api(`/api/todos/${id}`, { method: 'DELETE' });
}

export function clearCompletedTodos() {
  return api('/api/todos?completed=true', { method: 'DELETE' });
}

export function clearAllTodos() {
  return api('/api/todos', { method: 'DELETE' });
}

import { useCallback, useEffect, useState } from 'react';
import {
  clearAllTodos,
  clearCompletedTodos,
  createTodo,
  deleteTodo,
  fetchTodos,
  updateTodo,
} from './api.js';

export default function App() {
  const [todos, setTodos] = useState([]);
  const [title, setTitle] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    const data = await fetchTodos();
    setTodos(data);
  }, []);

  useEffect(() => {
    load()
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, [load]);

  async function handleSubmit(e) {
    e.preventDefault();
    const trimmed = title.trim();
    if (!trimmed) return;
    try {
      setError('');
      await createTodo(trimmed);
      setTitle('');
      await load();
    } catch (err) {
      setError(err.message);
    }
  }

  async function toggleCompleted(todo, completed) {
    try {
      setError('');
      await updateTodo(todo.id, { completed });
      await load();
    } catch (err) {
      setError(err.message);
    }
  }

  async function handleDelete(id) {
    try {
      setError('');
      await deleteTodo(id);
      await load();
    } catch (err) {
      setError(err.message);
    }
  }

  async function handleClearCompleted() {
    try {
      setError('');
      await clearCompletedTodos();
      await load();
    } catch (err) {
      setError(err.message);
    }
  }

  async function handleClearAll() {
    if (!window.confirm('Delete all todos?')) return;
    try {
      setError('');
      await clearAllTodos();
      await load();
    } catch (err) {
      setError(err.message);
    }
  }

  const active = todos.filter((t) => !t.completed).length;
  const hasCompleted = todos.some((t) => t.completed);

  return (
    <main className="app">
      <header className="header">
        <h1>Todo</h1>
        <p className="subtitle">Express + React + JSON file storage</p>
      </header>

      <form className="add-form" autoComplete="off" onSubmit={handleSubmit}>
        <input
          type="text"
          name="title"
          placeholder="What needs to be done?"
          maxLength={500}
          required
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <button type="submit">Add</button>
      </form>

      {todos.length > 0 && (
        <div className="toolbar">
          <span className="count">
            {active} item{active === 1 ? '' : 's'} left
          </span>
          <div className="toolbar-actions">
            {hasCompleted && (
              <button
                type="button"
                className="link-btn"
                onClick={handleClearCompleted}
              >
                Clear completed
              </button>
            )}
            <button
              type="button"
              className="link-btn danger"
              onClick={handleClearAll}
            >
              Clear all
            </button>
          </div>
        </div>
      )}

      {error && (
        <p className="error" role="alert">
          {error}
        </p>
      )}

      {loading ? (
        <p className="empty">Loading…</p>
      ) : (
        <>
          <ul className="todo-list">
            {todos.map((todo) => (
              <li
                key={todo.id}
                className={`todo-item${todo.completed ? ' completed' : ''}`}
              >
                <input
                  type="checkbox"
                  checked={todo.completed}
                  aria-label={`Mark "${todo.title}" as ${todo.completed ? 'incomplete' : 'complete'}`}
                  onChange={(e) => toggleCompleted(todo, e.target.checked)}
                />
                <span className="todo-title">{todo.title}</span>
                <button
                  type="button"
                  className="todo-delete"
                  onClick={() => handleDelete(todo.id)}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
          {todos.length === 0 && (
            <p className="empty">No todos yet. Add one above.</p>
          )}
        </>
      )}
    </main>
  );
}

:root {
  --bg: #0f1419;
  --surface: #1a2332;
  --border: #2d3a4f;
  --text: #e7ecf3;
  --muted: #8b9cb3;
  --accent: #5b9fd4;
  --accent-hover: #7ab3de;
  --done: #6bcf8a;
  --danger: #e07a7a;
  --radius: 10px;
  --font: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font);
  background: radial-gradient(ellipse 120% 80% at 50% -20%, #1e3a5f 0%, var(--bg) 55%);
  color: var(--text);
  line-height: 1.5;
}

.app {
  max-width: 520px;
  margin: 0 auto;
  padding: 3rem 1.25rem 4rem;
}

.header h1 {
  margin: 0;
  font-size: 2rem;
  font-weight: 650;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0.35rem 0 1.75rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.add-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.25rem;
}

.add-form input {
  flex: 1;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font-size: 1rem;
}

.add-form input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.add-form button,
.todo-list button {
  cursor: pointer;
  font-family: inherit;
}

.add-form button {
  padding: 0.75rem 1.25rem;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: #0a1628;
  font-weight: 600;
  font-size: 0.95rem;
}

.add-form button:hover {
  background: var(--accent-hover);
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.toolbar-actions {
  display: flex;
  gap: 0.75rem;
}

.link-btn {
  padding: 0;
  border: none;
  background: none;
  color: var(--accent);
  font-size: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.link-btn:hover {
  color: var(--accent-hover);
}

.link-btn.danger {
  color: var(--danger);
}

.error {
  margin: 0 0 1rem;
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius);
  background: rgba(224, 122, 122, 0.15);
  color: var(--danger);
  font-size: 0.9rem;
}

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.85rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  transition: border-color 0.15s;
}

.todo-item:hover {
  border-color: #3d4f6a;
}

.todo-item.completed .todo-title {
  color: var(--muted);
  text-decoration: line-through;
}

.todo-item input[type='checkbox'] {
  width: 1.15rem;
  height: 1.15rem;
  accent-color: var(--done);
  cursor: pointer;
}

.todo-title {
  flex: 1;
  word-break: break-word;
}

.todo-delete {
  padding: 0.35rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: transparent;
  color: var(--muted);
  font-size: 0.8rem;
}

.todo-delete:hover {
  border-color: var(--danger);
  color: var(--danger);
}

.empty {
  text-align: center;
  color: var(--muted);
  margin-top: 2rem;
}

